# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ASHÂB-I KEHF KISSASI (قِصَّةُ أَصْحَابِ الْكَهْفِ) VE ANAHTAR İFADELER</text>\n  <rect x="25" y="48" width="315" height="192" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">KISSADAKİ TEMEL KELİMELER</text>\n  <text x="40" y="98" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">الْكَهْفُ (el-Kehf):</tspan> Dağdaki geniş mağara</text>\n  <text x="40" y="122" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">الْفِتْيَةُ (el-Fitye):</tspan> İmanlı gençler (çoğul)</text>\n  <text x="40" y="146" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">الرَّقِيمُ (er-Rakîm):</tspan> Kitabe / yazılı levha</text>\n  <text x="40" y="170" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">الْبَعْثُ (el-Ba\'s):</tspan> Uyandırma / yeniden diriliş</text>\n  <rect x="40" y="186" width="285" height="38" rx="6" fill="#eff6ff" stroke="#60a5fa"/>\n  <text x="182" y="209" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">إِنَّهُمْ فِتْيَةٌ آمَنُوا بِرَبِّهِمْ وَزِدْنَاهُمْ هُدًى</text>\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">ASHÂB-I KEHF\'İN DUASI (KEHF, 10)</text>\n  <rect x="375" y="88" width="285" height="54" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="517" y="110" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">رَبَّنَا آتِنَا مِنْ لَدُنْكَ رَحْمَةً</text>\n  <text x="517" y="130" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا</text>\n  <text x="375" y="164" font-size="11" fill="#14532d">• <tspan font-weight="bold">آتِنَا (Âtinâ):</tspan> Bize ver / bahşet</text>\n  <text x="375" y="184" font-size="11" fill="#14532d">• <tspan font-weight="bold">رَحْمَةً (Rahmeten):</tspan> Katından bir rahmet</text>\n  <text x="375" y="204" font-size="11" fill="#14532d">• <tspan font-weight="bold">رَشَدًا (Reşeden):</tspan> Doğruluk ve kurtuluş yolu</text>\n  <text x="517" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Kıssanın Gayesi: Haşir ve Ba\'s inancını pekiştirmek</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KUR\'AN KISSALARININ ÖZELLİKLERİ VE ULÜ\'L-AZM PEYGAMBERLER</text>\n  <rect x="25" y="48" width="315" height="192" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">خَصَائِصُ الْقَصَصِ الْقُرْآنِيِّ (Özellikleri)</text>\n  <text x="40" y="98" font-size="11" fill="#78350f">• <tspan font-weight="bold">الْقَصَصُ الْحَقُّ:</tspan> Tamamen gerçek ve doğru haberdir.</text>\n  <text x="40" y="122" font-size="11" fill="#78350f">• <tspan font-weight="bold">أَحْسَنُ الْقَصَصِ:</tspan> En güzel anlatım (Yûsuf, 3).</text>\n  <text x="40" y="146" font-size="11" fill="#78350f">• <tspan font-weight="bold">الْعِبْرَةُ وَالْمَوْعِظَةُ:</tspan> İbret ve öğüt odaklıdır.</text>\n  <text x="40" y="170" font-size="11" fill="#78350f">• <tspan font-weight="bold">تَثْبِيتُ الْفُؤَادِ:</tspan> Kalpleri imanda sabit kılar.</text>\n  <rect x="40" y="186" width="285" height="38" rx="6" fill="#ffffff" stroke="#fbbf24"/>\n  <text x="182" y="209" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">لَقَدْ كَانَ فِي قَصَصِهِمْ عِبْرَةٌ لِأُولِي الْأَلْبَابِ</text>\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">أُولُو الْعَزْمِ مِنَ الرُّسُلِ (Ulü\'l-Azm)</text>\n  <text x="375" y="96" font-size="11" fill="#581c87">1. <tspan font-weight="bold">نُوحٌ (Hz. Nûh):</tspan> Tufan ve gemi ({ar:السَّفِينَة})</text>\n  <text x="375" y="118" font-size="11" fill="#581c87">2. <tspan font-weight="bold">إِبْرَاهِيمُ (Hz. İbrâhîm):</tspan> Putlarla mücadele</text>\n  <text x="375" y="140" font-size="11" fill="#581c87">3. <tspan font-weight="bold">مُوسَى (Hz. Mûsâ):</tspan> Firavun\'a karşı tevhid</text>\n  <text x="375" y="162" font-size="11" fill="#581c87">4. <tspan font-weight="bold">عِيسَى (Hz. Îsâ):</tspan> İncil ve tevhid daveti</text>\n  <text x="375" y="184" font-size="11" fill="#581c87">5. <tspan font-weight="bold">مُحَمَّدٌ (Hz. Muhammed):</tspan> Son peygamber</text>\n  <rect x="375" y="196" width="285" height="30" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="517" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Ortak Mesaj: اُعْبُدُوا اللَّهَ (Allah\'a kulluk edin!)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KISSALARDA MÜCERRED-MEZÎD FİİLLER VE ŞART ÜSLUBU (أُسْلُوبُ الشَّرْطِ)</text>\n  <rect x="25" y="48" width="315" height="192" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">MÜCERRED VE MEZÎD FİİL ÖRNEKLERİ</text>\n  <text x="40" y="98" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Mücerred (Yalın 3 Harfli):</tspan></text>\n  <text x="50" y="118" font-size="11" fill="#1e3a8a">لَبِثَ (kaldı) | بَعَثَ (diriltti) | عَبَدَ (kulluk etti)</text>\n  <text x="40" y="144" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Mezîd (Harf Eklenmiş):</tspan></text>\n  <text x="50" y="164" font-size="11" fill="#1e3a8a">آمَنَ (iman etti - İf\'âl) | هَيَّأَ (kolaylaştırdı - Tef\'îl)</text>\n  <text x="50" y="184" font-size="11" fill="#1e3a8a">اِزْدَادَ (arttı - İfti\'âl) | أَرْسَلَ (gönderdi - İf\'âl)</text>\n  <rect x="40" y="196" width="285" height="30" rx="5" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="182" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">آتِنَا (Bize ver) → آتَى mezîd fiilinin emri</text>\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">ŞART EDATLARI (أَدَوَاتُ الشَّرْطِ)</text>\n  <text x="375" y="98" font-size="11" fill="#14532d">• <tspan font-weight="bold">Cezmeden Edatlar (أَدَوَاتٌ جَازِمَةٌ):</tspan></text>\n  <text x="385" y="118" font-size="11" fill="#14532d"><tspan font-weight="bold">إِنْ</tspan> (eğer)  |  <tspan font-weight="bold">مَنْ</tspan> (kim ... ise)  |  <tspan font-weight="bold">مَا</tspan> (ne ... ise)</text>\n  <text x="375" y="144" font-size="11" fill="#14532d">• <tspan font-weight="bold">Cezmetmeyen Edatlar (غَيْرُ جَازِمَةٍ):</tspan></text>\n  <text x="385" y="164" font-size="11" fill="#14532d"><tspan font-weight="bold">إِذَا</tspan> (-dığı zaman / şayet)  |  <tspan font-weight="bold">لَوْ</tspan> (eğer olsaydı)</text>\n  <rect x="375" y="182" width="285" height="44" rx="5" fill="#ffffff" stroke="#4ade80"/>\n  <text x="517" y="200" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Yapı: [Şart Edatı] + [Şart Fiili] + [Cevap Fiili]</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" fill="#14532d">مَنْ يَصْبِرْ يَظْفَرْ (Kim sabrederse zafere erer)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
